package com.tourist.Yatra_secure.service;
import com.tourist.Yatra_secure.Repository.*;import com.tourist.Yatra_secure.dto.*;import com.tourist.Yatra_secure.entity.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import java.util.*;
@Service public class IncidentService{
 private final IncidentRepository incidents;private final UserRepository users;
 public IncidentService(IncidentRepository incidents,UserRepository users){this.incidents=incidents;this.users=users;}
 public Map<String,Object> create(String email,IncidentRequest r,boolean sos){if((r.latitude()==null)!=(r.longitude()==null))throw new AuthException(HttpStatus.BAD_REQUEST,"Latitude and longitude must be provided together");user u=users.findByEmail(email).orElseThrow(()->new AuthException(HttpStatus.NOT_FOUND,"Tourist not found"));String priority=sos?"CRITICAL":Objects.toString(r.priority(),"MEDIUM");return view(incidents.save(new Incident(u,sos?"SOS":r.incidentType(),r.description(),r.latitude(),r.longitude(),priority,"OPEN")));}
 public List<Map<String,Object>> mine(String email){return incidents.findByTourist_EmailOrderByCreatedAtDesc(email).stream().map(this::view).toList();}
 public List<Map<String,Object>> all(String status){if(status!=null&&!status.matches("OPEN|IN_PROGRESS|RESOLVED|CANCELLED"))throw new AuthException(HttpStatus.BAD_REQUEST,"Invalid incident status");return (status==null?incidents.findAllByOrderByCreatedAtDesc():incidents.findByStatusOrderByCreatedAtDesc(status)).stream().map(this::view).toList();}
 public Map<String,Object> cancel(String email,Long id){Incident i=incidents.findById(id).filter(x->x.getTourist().getEmail().equals(email)).orElseThrow(()->new AuthException(HttpStatus.NOT_FOUND,"Incident not found"));if(!"OPEN".equals(i.getStatus()))throw new AuthException(HttpStatus.CONFLICT,"Only open incidents can be cancelled");i.setStatus("CANCELLED");return view(incidents.save(i));}
 public Map<String,Object> adminUpdate(Long id,IncidentUpdateRequest r){Incident i=incidents.findById(id).orElseThrow(()->new AuthException(HttpStatus.NOT_FOUND,"Incident not found"));if(r.status()!=null)i.setStatus(r.status());if(r.assignedTo()!=null)i.setAssignedTo(r.assignedTo().isBlank()?null:r.assignedTo().trim());return view(incidents.save(i));}
 private Map<String,Object> view(Incident i){Map<String,Object> m=new LinkedHashMap<>();m.put("id",i.getId());m.put("touristId",i.getTourist().getId());m.put("touristName",i.getTourist().getName());m.put("incidentType",i.getIncidentType());m.put("description",i.getDescription());m.put("latitude",i.getLatitude());m.put("longitude",i.getLongitude());m.put("priority",i.getPriority());m.put("status",i.getStatus());m.put("assignedTo",i.getAssignedTo());m.put("createdAt",i.getCreatedAt());m.put("updatedAt",i.getUpdatedAt());return m;}
}
